This adds the ability to define a "more" section menu to custom sidebar/navigation sections. This includes the ability to add a custom button w/ action at the bottom of the menu, as well as customize the "more" trigger icon and text. 

This also allows API added sections to be visible for anonymous users. 




Here's a working example for a custom "site info" section

```js
import { apiInitializer } from "discourse/lib/api";

export default apiInitializer((api) => {
  api.addSidebarSection(
    (BaseCustomSidebarSection, BaseCustomSidebarSectionLink) => {
      return class extends BaseCustomSidebarSection {
        get name() {
          return "about-section";
        }

        get text() {
          return "Site info";
        }

        get actionsIcon() {
          return "gear";
        }

        get actions() {
          return [
            {
              id: "action-example",
              title: "action-example",
              action: () => {
                console.log("Custom action...");
              },
            },
          ];
        }

        get links() {
          return [
            new (class extends BaseCustomSidebarSectionLink {
              get name() {
                return "about";
              }
              get route() {
                return "about";
              }
              get title() {
                return "About";
              }
              get text() {
                return "About";
              }
              get prefixType() {
                return "icon";
              }
              get prefixValue() {
                return "circle-info";
              }
            })(),

            new (class extends BaseCustomSidebarSectionLink {
              get name() {
                return "faq";
              }
              get route() {
                return "faq";
              }
              get title() {
                return "FAQ";
              }
              get text() {
                return "FAQ";
              }
              get prefixType() {
                return "icon";
              }
              get prefixValue() {
                return "circle-question";
              }
            })(),
          ];
        }

        get moreLinks() {
          const links = [
            new (class extends BaseCustomSidebarSectionLink {
              get name() {
                return "terms";
              }
              get route() {
                return "tos";
              }
              get title() {
                return "Terms of Service";
              }
              get text() {
                return "Terms of Service";
              }
              get prefixType() {
                return "icon";
              }
              get prefixValue() {
                return "gavel";
              }
            })(),

            new (class extends BaseCustomSidebarSectionLink {
              get name() {
                return "privacy";
              }
              get href() {
                return "https://meta.discourse.org/privacy";
              }
              get title() {
                return "Privacy policy";
              }
              get text() {
                return "Privacy policy";
              }
              get prefixType() {
                return "icon";
              }
              get prefixValue() {
                return "user";
              }
            })(),
          ];

          return links;
        }

        get moreSectionText() {
          return "Legal";
        }

        get moreSectionIcon() {
          return "scroll";
        }
      };
    },
  );
});
```
